int main (void)
{
  hb_blob_t *blob = hb_blob_create ((const char *) font_bytes, sizeof (font_bytes),
				     HB_MEMORY_MODE_READONLY, NULL, NULL);
  hb_face_t *face = hb_face_create (blob, 0);
  hb_font_t *font = hb_font_create (face);

  hb_buffer_t *buf = hb_buffer_create ();
  hb_buffer_add_utf8 (buf, "A", -1, 0, -1);
  hb_buffer_guess_segment_properties (buf);

  /* 'ccmp' is one of HarfBuzz's always-on global GSUB features, so this
   * single call is enough to make the shaper build (and exercise) the
   * accelerator cache for our GSUB lookup. */
  hb_shape (font, buf, NULL, 0);

  hb_buffer_destroy (buf);
  hb_font_destroy (font);
  hb_face_destroy (face);
  hb_blob_destroy (blob);

  return 0;
}
